    $media=$db->query("SELECT * FROM media WHERE mime_type LIKE 'image/%' ORDER BY id DESC LIMIT 500")->fetchAll();$mediaPaths=array_column($media,'path');$usageContexts=media_usage_contexts($db);$contentUsage=media_content_usage_map($db,$mediaPaths);$staticUsage=media_static_usage_map($mediaPaths);$mediaStats=['total'=>count($media),'used'=>0,'unused'=>0,'protected'=>0,'structural'=>0,'uploads'=>0,'remote'=>0,'r2'=>0,'deletable'=>0,'hero'=>0,'gallery'=>0,'product'=>0];
    foreach($media as &$item){$path=(string)$item['path'];$managed=str_starts_with($path,'/uploads/')||preg_match('#^https?://#i',$path);$item['usage_count']=($contentUsage[$path]??0)+($managed?0:($staticUsage[$path]??0));$item['contexts']=$usageContexts[$path]??[];$item['remote']=(bool)preg_match('#^https?://#i',$path);$item['structural']=!$item['remote']&&!str_starts_with($path,'/uploads/');$item['filter']=$item['remote']?'r2':($item['structural']?'structural':'uploads');$item['protection_reason']=media_protection_reason($path);$item['deletable']=$item['usage_count']===0&&$item['protection_reason']==='';$item['status']=$item['deletable']?'unused':($item['protection_reason']!==''?'protected':'used');$item['kinds']=[];foreach($item['contexts'] as $context){if($context==='Hero')$item['kinds'][]='hero';if(str_contains($context,'Galería'))$item['kinds'][]='gallery';if(in_array($context,['Producto','Galería de producto','Empaque'],true))$item['kinds'][]='product';}if($item['structural']&&($staticUsage[$path]??0)>0)$item['contexts'][]='Sitio estático';if($item['protection_reason']!==''&&$item['usage_count']===0)$item['contexts'][]=$item['protection_reason'];$item['contexts']=array_values(array_unique($item['contexts']));$item['kinds']=array_values(array_unique($item['kinds']));if($item['usage_count']>0)$mediaStats['used']++;if($item['deletable'])$mediaStats['unused']++;if($item['protection_reason']!=='')$mediaStats['protected']++;$mediaStats[$item['filter']]++;if($item['remote'])$mediaStats['remote']++;if($item['deletable'])$mediaStats['deletable']++;foreach($item['kinds'] as $kind)$mediaStats[$kind]++;}unset($item);$localDuplicateGroups=(int)$db->query("SELECT COUNT(*) FROM (SELECT content_hash FROM media WHERE path NOT REGEXP '^https?://' AND content_hash IS NOT NULL AND content_hash<>'' GROUP BY content_hash HAVING COUNT(*)>1) duplicate_groups")->fetchColumn();
    $localMediaCount=$mediaStats['total']-$mediaStats['remote'];$recoverableAliases=(int)$db->query("SELECT COUNT(*) FROM media m INNER JOIN media_aliases a ON a.local_path=m.path WHERE m.path NOT REGEXP '^https?://' AND m.mime_type LIKE 'image/%' AND a.remote_path REGEXP '^https?://'")->fetchColumn();$r2Values=[];foreach($db->query("SELECT setting_key,value_text FROM settings WHERE setting_key LIKE 'r2_%'") as $item)$r2Values[$item['setting_key']]=$item['value_text'];try{r2_settings($db);$r2Ready=true;}catch(Throwable){$r2Ready=false;} ?>
<header class="media-heading"><div><p class="admin-eyebrow">Inventario central</p><h2>Biblioteca de la web</h2><p>Héroes, galerías, productos y cargas del panel, reunidos por contenido para evitar duplicados.</p></div><div class="media-heading-actions"><?php if($localDuplicateGroups&&can('media','delete',$user)):?><form method="post" onsubmit="return confirm('Se conservará una sola copia local por contenido idéntico y se actualizarán todas sus referencias. ¿Continuar?')"><?=csrf_field()?><input type="hidden" name="action" value="optimize-media-local"><button class="secondary-button">Consolidar <?=$localDuplicateGroups?> repetida<?=$localDuplicateGroups===1?'':'s'?></button></form><?php endif;?><?php if(can('media','upload',$user)):?><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="scan-public-media"><button class="primary-button">Escanear web pública</button></form><?php endif;?></div></header>
