<section class="media-control-grid"><form method="post" enctype="multipart/form-data" class="admin-panel media-upload"><?=csrf_field()?><input type="hidden" name="action" value="upload-media"><div><p class="admin-eyebrow">Nueva imagen</p><h2>Subir a la biblioteca</h2><p>JPG, PNG, WebP o AVIF. Máximo 8 MB. Se guarda la versión más liviana en R2.</p></div><label><span>Seleccionar archivo</span><input type="file" name="image" accept="image/jpeg,image/png,image/webp,image/avif" required></label><button class="primary-button">Subir imagen</button></form><section class="admin-panel media-sync-panel"><div><p class="admin-eyebrow">Cloudflare R2</p><h2>Almacenamiento externo</h2><p><strong><?=$localMediaCount?></strong> imágenes locales · <strong><?=$mediaStats['remote']?></strong> vinculadas en MySQL</p><?php if($r2Ready&&$localMediaCount>0):?><small class="media-recovery-note"><?=$recoverableAliases===$localMediaCount?'Los archivos ya existen en R2. Finaliza sus vínculos y retira los registros locales antiguos.':'Migra imágenes locales y elimina de Hostinger únicamente las copias verificadas.'?></small><?php endif;?></div><?php if($r2Ready&&can('media','sync',$user)):?><div class="media-r2-actions"><?php if($localMediaCount>0):?><form method="post" onsubmit="return confirm('Se compararán las cargas locales con el bucket R2 y se restaurarán en MySQL las coincidencias exactas. No se subirá ni eliminará ningún archivo. ¿Continuar?')"><?=csrf_field()?><input type="hidden" name="action" value="reconcile-media-r2"><button class="secondary-button">Recuperar vínculos</button></form><form method="post" onsubmit="return confirm('Se verificarán los objetos existentes en R2, se actualizarán sus referencias en MySQL y solo se retirarán las copias locales confirmadas. ¿Continuar?')"><?=csrf_field()?><input type="hidden" name="action" value="sync-media-r2"><button class="primary-button"><?=$recoverableAliases===$localMediaCount?'Finalizar vinculación':'Migrar y limpiar'?></button></form><?php else:?><span class="status published media-sync-complete">Migración completa</span><?php endif;?><form method="post" onsubmit="return confirm('Se conservará una sola copia de cada contenido idéntico en R2, se actualizarán sus referencias y se eliminarán únicamente duplicados verificados. ¿Continuar?')"><?=csrf_field()?><input type="hidden" name="action" value="optimize-media-r2"><button class="secondary-button">Optimizar duplicados</button></form></div><?php elseif(!$r2Ready):?><a class="secondary-button" href="/admin/configuration.php">Configurar R2</a><?php else:?><span class="status published">Todo vinculado</span><?php endif;?></section></section>
