<?php if(!$media):?><div class="admin-panel content-empty"><strong>La biblioteca está vacía</strong><p>Escanea la web pública o sube una imagen para comenzar.</p></div><?php endif;?>
</section>

<?php elseif ($view==='inquiries'): $statusLabels=['new'=>'Nueva','contacted'=>'Contactada','closed'=>'Cerrada','spam'=>'No deseada'];$statusDescriptions=['new'=>'Pendiente de revisión','contacted'=>'El equipo ya respondió','closed'=>'Atención finalizada','spam'=>'Consulta descartada'];$statusFilter=in_array($_GET['status']??'',array_keys($statusLabels),true)?$_GET['status']:'';$inquiryCounts=['all'=>scalar($db,'SELECT COUNT(*) FROM inquiries')];foreach($statusLabels as $statusKey=>$statusLabel){$countStatement=$db->prepare('SELECT COUNT(*) FROM inquiries WHERE status=?');$countStatement->execute([$statusKey]);$inquiryCounts[$statusKey]=(int)$countStatement->fetchColumn();}$query='SELECT * FROM inquiries';$queryParams=[];if($statusFilter!==''){$query.=' WHERE status=?';$queryParams[]=$statusFilter;}$query.=' ORDER BY created_at DESC LIMIT 200';$statement=$db->prepare($query);$statement->execute($queryParams);$rows=$statement->fetchAll(); ?><div class="inquiry-toolbar"><div><p class="admin-eyebrow">Bandeja comercial</p><h2>Seguimiento de consultas</h2><p>Revisa los datos enviados y actualiza el avance de cada oportunidad.</p></div><nav class="inquiry-filters" aria-label="Filtrar consultas por estado"><a class="<?=$statusFilter===''?'active':''?>" href="/admin/?view=inquiries">Todas <span><?=$inquiryCounts['all']?></span></a><?php foreach($statusLabels as $statusKey=>$statusLabel):?><a class="<?=$statusFilter===$statusKey?'active':''?>" href="/admin/?view=inquiries&status=<?=e($statusKey)?>"><?=e($statusLabel)?> <span><?=$inquiryCounts[$statusKey]?></span></a><?php endforeach;?></nav></div><section class="inquiry-grid"><?php foreach($rows as $row):$createdAt=new DateTimeImmutable((string)$row['created_at']);?><article class="admin-panel inquiry-card status-<?=e($row['status'])?>"><header class="inquiry-head"><div><span class="status <?=e($row['status'])?>"><?=e($statusLabels[$row['status']]??'Nueva')?></span><small><?=e($statusDescriptions[$row['status']]??'Pendiente de revisión')?></small></div><time datetime="<?=e($createdAt->format(DATE_ATOM))?>"><span>Recibida</span><?=e($createdAt->format('d/m/Y · H:i'))?></time></header><div class="inquiry-main"><section class="inquiry-person"><p class="inquiry-label">Contacto</p><h2><?=e($row['name'])?></h2><?php if(!empty($row['company'])):?><p class="inquiry-company"><?=e($row['company'])?></p><?php endif;?><div class="inquiry-contact"><a href="mailto:<?=e($row['email'])?>">Enviar correo</a><?php if(!empty($row['phone'])):?><a href="tel:<?=e(preg_replace('/[^\d+]/','',(string)$row['phone']))?>">Llamar · <?=e($row['phone'])?></a><?php endif;?></div></section><section class="inquiry-information"><dl class="inquiry-details"><?php if(!empty($row['participant_type'])):?><div><dt>Tipo de participante</dt><dd><?=e($row['participant_type'])?></dd></div><?php endif;?><?php if(!empty($row['email'])):?><div><dt>Correo electrónico</dt><dd><?=e($row['email'])?></dd></div><?php endif;?><?php if(!empty($row['country'])):?><div><dt>País</dt><dd><?=e($row['country'])?></dd></div><?php endif;?><?php if(!empty($row['product_line'])):?><div><dt>Línea solicitada</dt><dd><?=e($row['product_line']==='retail'?'Retail':'Convencional')?></dd></div><?php endif;?><?php $selectedProducts=trim((string)($row['product_names']??$row['product_name']??''));if($selectedProducts!==''):?><div class="wide"><dt>Productos de interés</dt><dd><?=e($selectedProducts)?></dd></div><?php endif;?></dl></section></div><section class="inquiry-request"><p class="inquiry-label">Mensaje de la consulta</p><p class="inquiry-message"><?=nl2br(e($row['message']))?></p></section><form method="post" class="inquiry-status-form"><?=csrf_field()?><input type="hidden" name="action" value="inquiry-status"><input type="hidden" name="id" value="<?=$row['id']?>"><label for="inquiry-status-<?=$row['id']?>"><span>Actualizar estado</span><small>Selecciona el siguiente paso de esta consulta.</small></label><select id="inquiry-status-<?=$row['id']?>" name="status"><?php foreach($statusLabels as $statusKey=>$statusLabel):?><option value="<?=e($statusKey)?>" <?=$row['status']===$statusKey?'selected':''?>><?=e($statusLabel)?> — <?=e($statusDescriptions[$statusKey])?></option><?php endforeach;?></select><button class="primary-button" type="submit">Guardar estado</button></form></article><?php endforeach;?><?php if(!$rows):?><div class="admin-panel content-empty inquiry-empty"><strong>No hay consultas en este estado</strong><p>Selecciona otro filtro para revisar la bandeja.</p></div><?php endif;?></section>

<?php elseif ($view==='settings'): $settings=[];foreach($db->query('SELECT setting_key,value_text FROM settings') as $item)$settings[$item['setting_key']]=$item['value_text'];?><form method="post" class="admin-panel admin-form"><?=csrf_field()?><input type="hidden" name="action" value="save-settings"><div class="form-grid"><label>Correo comercial<input type="email" name="company_email" value="<?=e($settings['company_email']??'')?>"></label><label>Teléfono<input name="company_phone" value="<?=e($settings['company_phone']??'')?>"></label><label>WhatsApp<input name="whatsapp" value="<?=e($settings['whatsapp']??'')?>"></label><label>Instagram<input name="instagram" value="<?=e($settings['instagram']??'')?>"></label><label>Facebook<input name="facebook" value="<?=e($settings['facebook']??'')?>"></label><label class="wide">Dirección en español<textarea name="address_es"><?=e($settings['address_es']??'')?></textarea></label><label class="wide">Address in English<textarea name="address_en"><?=e($settings['address_en']??'')?></textarea></label></div><button class="primary-button">Guardar configuración</button></form>

<?php elseif ($view==='users' && $user['role']==='admin'): $users=$db->query('SELECT id,name,email,role,is_active,last_login_at FROM admin_users ORDER BY id')->fetchAll();?><div class="admin-two-cols"><form method="post" class="admin-panel admin-form"><?=csrf_field()?><input type="hidden" name="action" value="save-user"><h2>Nuevo usuario</h2><label>Nombre<input name="name" required></label><label>Correo<input type="email" name="email" required></label><label>Rol<select name="role"><option value="editor">Editor</option><option value="admin">Administrador</option></select></label><label>Contraseña<input type="password" name="password" minlength="10" required></label><button class="primary-button">Crear usuario</button></form><section class="admin-panel"><h2>Equipo</h2><?php foreach($users as $item):?><div class="user-row"><div><strong><?=e($item['name'])?></strong><small><?=e($item['email'])?></small></div><span><?=e($item['role'])?></span></div><?php endforeach;?></section></div><?php endif; ?>
</main><script>document.querySelectorAll('[data-copy]').forEach(b=>b.addEventListener('click',()=>navigator.clipboard.writeText(b.dataset.copy).then(()=>b.textContent='Copiado')));document.querySelectorAll('[data-media-filter]').forEach(button=>button.addEventListener('click',()=>{document.querySelectorAll('[data-media-filter]').forEach(item=>item.classList.toggle('active',item===button));document.querySelectorAll('[data-media-item]').forEach(item=>{const filter=button.dataset.mediaFilter;item.hidden=filter!=='all'&&item.dataset.source!==filter&&item.dataset.status!==filter&&!item.dataset.kinds.split(' ').includes(filter);});}));document.querySelectorAll('form input[name="action"][value="delete-media"]').forEach(input=>{const form=input.form,button=form?.querySelector('.danger-button'),card=form?.closest('[data-media-item]'),uses=card?.querySelector('.media-card-copy>p span')?.textContent?.trim()||'';if(!button)return;const inUse=!(uses.startsWith('0 ')||uses==='0 usos');button.disabled=inUse;button.textContent=inUse?'En uso':'Eliminar';if(inUse){button.title='Reemplaza o retira esta imagen desde su editor antes de eliminarla.';form.onsubmit=()=>false;}else{button.removeAttribute('title');form.onsubmit=()=>confirm('La imagen se eliminará definitivamente de la biblioteca y de Cloudflare R2. ¿Continuar?');}});</script></body></html>
